import React from 'react';
import { chakra, useStyleConfig, useToken } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import { useCountryConfig } from 'app/hooks/useCountryConfig';

const ZIMM_CART_BUTTON_GROUP_RECIPE = 'ZimmCartButtonGroup';

const messages = defineMessages({
  checkout: { id: 'zimm_cart_button_group.checkout', defaultMessage: 'Checkout' },
  applePay: { id: 'zimm_cart_button_group.apple_pay', defaultMessage: 'Apple Pay' },
  googlePay: { id: 'zimm_cart_button_group.google_pay', defaultMessage: 'Google Pay' },
});

export { messages };

// `use-navigation.js` (base SFCC hook, no override exists) ships no TypeScript types of its own
// — same "Commerce SDK types not importable" gotcha AGENTS.md documents, generalised to any
// untyped upstream hook. A narrow local type from its own JSDoc contract (`@param {string} path`,
// `@param {('push'|'replace')} action`) is used instead of `any`, matching typescript.md's
// preference for `unknown`/a narrow type over an unexplained `any`.
type NavigateFn = (path: string, action?: 'push' | 'replace', ...args: unknown[]) => void;

/**
 * Real, confirmed intrinsic dimensions of the two downloaded Pay-mark SVGs (Figma export,
 * 2026-09-21 — see plan.md step 5.1's own "Real asset dimensions" correction). These are NOT a
 * spacing/layout decision — they describe a specific vector asset's own fixed shape — so they
 * don't route through the `--zimm-scale-*` spacing scale the way a real layout gap/size would.
 * Named constants per conventions.md's "no magic numbers" rule; each is also flagged for
 * `npm run audit:tokens` (a raw px string) with the required exception vocabulary, since there is
 * no applicable design token for an asset's own intrinsic size.
 * audit-allow: real SVG asset intrinsic size, not a design/spacing token
 */
const PAY_MARK_SLOT_WIDTH = '48px'; // shared slot — matches Apple's own native width exactly
const PAY_MARK_SLOT_HEIGHT = '24px'; // shared slot — matches Apple's own native height exactly
const GOOGLE_PAY_LOGO_WIDTH = '45px'; // native 45.1717, rounded per plan.md step 5.1
const GOOGLE_PAY_LOGO_HEIGHT = '18px'; // native 18 exactly

/**
 * International checkout stub (SFCC-11 plan step 5.1, AC6/AC7). Neither SFCC-880 (guest —
 * intermediate login interstitial) nor SFCC-63 (authenticated — straight to Global-e) exists yet
 * (SFCC-880: To Do, unassigned, no sprint; Global-e: "Not started", PRC-43/PRC-46 open — see
 * session-notes.md §SFCC-275) — so both auth states fall through to the same base `/checkout`
 * path, which is this app's actual current behaviour today regardless of region. That makes this
 * a no-op stub, not a regression: replace this body with the real guest-login-interstitial /
 * Global-e-handoff branch once either card lands. Exported (not a closure inside the component)
 * so a test can call it directly and prove the international branch is reached without waiting on
 * either ticket — see this component's own index.test.tsx.
 */
export const navigateInternationalCheckoutStub = (navigate: NavigateFn): void => {
  // TODO(SFCC-880, SFCC-63): replace with the real guest-interstitial / Global-e branch.
  navigate('/checkout');
};

/**
 * Apple Pay wordmark — inlined SVG markup, deliberately NOT `<img src={...}>` despite
 * `overrides/app/assets/svg/apple-pay-logo.svg` existing on disk as the committed source of
 * truth for this exact path data (copied verbatim below, not redrawn). `<img src>` would not
 * work here: this project's real webpack build (`node_modules/@salesforce/pwa-kit-dev/configs/
 * webpack/config.js`, unscoped `test: /\.svg$/`, not limited to `node_modules`) resolves every
 * `.svg` import via `svg-sprite-loader` server-side and `ignore-loader` client-side — neither
 * yields an `<img src>`-compatible URL, for a project-owned SVG exactly as much as a base-package
 * one. `ZimmLogo` (`app/components/ui-kits/atoms/zimmLogo/index.tsx`) already documents and works
 * around this identical constraint by inlining; this follows the same established pattern rather
 * than reinventing one. See this folder's own index.test.tsx for the byte-for-byte proof that the
 * path data below still matches the committed source file exactly.
 */
const ApplePayMark = () => {
  const [fill] = useToken('colors', ['text.default']);
  return (
    <chakra.svg
      viewBox="0 0 48 24"
      width={PAY_MARK_SLOT_WIDTH}
      height={PAY_MARK_SLOT_HEIGHT}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M10.0396 5.32065C9.52395 5.92864 8.69885 6.40818 7.87376 6.33968C7.77062 5.5176 8.17457 4.64415 8.64728 4.10466C9.16297 3.47954 10.0654 3.03425 10.796 3C10.8819 3.85633 10.5467 4.69553 10.0396 5.32065ZM10.7874 6.50238C9.5927 6.43387 8.56993 7.17888 8.00268 7.17888C7.42683 7.17888 6.55876 6.53663 5.61334 6.55376C4.3843 6.57088 3.2412 7.26451 2.61378 8.36917C1.32457 10.5785 2.27859 13.8497 3.52482 15.648C4.13505 16.5385 4.8656 17.5147 5.82821 17.4805C6.73925 17.4462 7.10023 16.8896 8.20036 16.8896C9.30908 16.8896 9.62708 17.4805 10.5897 17.4634C11.5867 17.4462 12.2141 16.5728 12.8243 15.6822C13.5205 14.6717 13.8041 13.687 13.8213 13.6356C13.8041 13.6185 11.8961 12.8906 11.8789 10.6984C11.8617 8.86584 13.383 7.99239 13.4517 7.94101C12.5923 6.67364 11.2515 6.53663 10.7874 6.50238ZM17.6889 4.01903V17.3692H19.7689V12.8049H22.6481C25.2781 12.8049 27.126 11.0067 27.126 8.40343C27.126 5.80019 25.3125 4.01903 22.7169 4.01903H17.6889ZM19.7689 5.76594H22.1668C23.9717 5.76594 25.0031 6.72502 25.0031 8.41199C25.0031 10.099 23.9717 11.0666 22.1582 11.0666H19.7689V5.76594ZM30.9248 17.4719C32.2312 17.4719 33.4431 16.8126 33.9932 15.7678H34.0361V17.3692H35.9613V10.7241C35.9613 8.79734 34.4143 7.55566 32.0336 7.55566C29.8247 7.55566 28.1917 8.81446 28.1315 10.5442H30.0052C30.1599 9.72217 30.9248 9.18268 31.9734 9.18268C33.2454 9.18268 33.9588 9.77355 33.9588 10.8611V11.5975L31.3632 11.7517C28.948 11.8972 27.6416 12.882 27.6416 14.5947C27.6416 16.3245 28.991 17.4719 30.9248 17.4719ZM31.4835 15.8877C30.3748 15.8877 29.67 15.3568 29.67 14.5433C29.67 13.7041 30.349 13.216 31.6468 13.1389L33.9588 12.9933V13.7469C33.9588 14.9971 32.893 15.8877 31.4835 15.8877ZM38.5312 21C40.5595 21 41.5135 20.2293 42.3472 17.8915L46 7.68411H43.8857L41.4362 15.5709H41.3932L38.9437 7.68411H36.7693L40.2931 17.4034L40.104 17.9943C39.786 18.9962 39.2703 19.3815 38.3507 19.3815C38.1874 19.3815 37.8694 19.3644 37.7405 19.3473V20.9486C37.8608 20.9829 38.3765 21 38.5312 21Z"
        fill={fill}
      />
    </chakra.svg>
  );
};

/**
 * Google Pay wordmark — same inlining rationale as `ApplePayMark` above (this project's webpack
 * config `ignore-loader`s every client-side `.svg` import, project-owned or not). Path data
 * copied verbatim from `overrides/app/assets/svg/google-pay-logo.svg`'s four `<path>` elements
 * (ids `Vector`–`Vector_4`), same order.
 */
const GooglePayMark = () => {
  const [fill] = useToken('colors', ['text.default']);
  return (
    <chakra.svg
